"""E2E over real HTTP against the local PHP server (port 8091, DB nuahn_book). Run from /workspace/tools."""
from lib import *
import io, re, subprocess, sys
from PIL import Image
P=F=0
def ok(name, cond, extra=''):
    global P,F
    if cond: P+=1; print('  PASS', name)
    else: F+=1; print('  FAIL', name, extra)
def img(color=(200,30,30), size=(640,480), exif=True):
    im=Image.new('RGB', size, color); b=io.BytesIO(); im.save(b,'JPEG'); return b.getvalue()
def sql(q):
    return subprocess.check_output(['mysql','-h127.0.0.1','-unuahn','-pnuahn_secret','nuahn_book','-N','-B','-e',q],stderr=subprocess.DEVNULL).decode().strip()
def loc(r): return r.headers.get('Location','')
def tid(r):
    m=re.search(r'(?:task|id)=(\d+)', loc(r)); return int(m.group(1)) if m else None
def row(t, col): return sql('select %s from tasks where id=%d'%(col,t))
def pay(t, col): return sql('select %s from payments where task_id=%d'%(col,t))
def fresh_log(): return int(subprocess.check_output("grep -c 'PHP ' /tmp/php8091.log",shell=True))
log0=fresh_log()

